# -*- coding: utf-8 -*-
"""
生成 Localization/zh.csv 与 en.csv（v3）。
规范：键,文本；UTF-8；无表头；语言代码必须是 zh / en；注释行以 # 开头。
覆盖：全部物品/设备 ×3 键 + 配置 + 王尔德人脉 + 手册 + 化学画像 + 品级。
"""
import csv, glob, os, re

ROOT = r"C:\Users\Administrator\WorkBuddy\Claw\ps-chem-mod"
OUT = os.path.join(ROOT, "FreeChem", "Localization")
os.makedirs(OUT, exist_ok=True)

# ── 从图标目录 + 源码自动取全量 id，避免漏项 ──
icons = {os.path.splitext(os.path.basename(p))[0]
         for p in glob.glob(os.path.join(ROOT, "FreeChem", "Textures", "Items", "*.png"))}
cat = open(os.path.join(ROOT, "src", "ChemCatalog.cs"), encoding="utf-8").read()
rec = open(os.path.join(ROOT, "src", "ChemRecipes.cs"), encoding="utf-8").read()
spec_ids = set(re.findall(r'\b[SCI]\("([a-z0-9_]+)"', cat))
m = re.search(r'string\[\]\s*MachineIds\s*=\s*\{(.*?)\};', rec, re.S)
machine_ids = set(re.findall(r'"([a-z0-9_]+)"', m.group(1))) if m else set()
# `<id>_on` 是机器「工作态」贴图（运行时由 SetSpriteAndShapeFromMod 切换），
# 不是独立物品，不生成 _name/_desc/_flavor 键。
item_icons = {i for i in icons if not i.endswith("_on")}
all_ids = sorted(item_icons | spec_ids | machine_ids)

