def rows(lang):
    out = []
    zh = lang == "zh"
    for i in all_ids:
        e = N.get(i)
        if e is None:
            name = i
            desc = "FreeChem 新增化合物 / 设备。" if zh else "FreeChem reagent / device."
            flavor = (lambda f: (f[0] if zh else f[1]))(FL[i]) if i in FL else FLAVOR[lang]
            out += [(i + "_name", name), (i + "_desc", desc), (i + "_flavor", flavor)]
        else:
            out += [(i + "_name", e[0] if zh else e[1]),
                    (i + "_desc", e[2] if zh else e[3]),
                    (i + "_flavor", (FL[i][0] if zh else FL[i][1]) if i in FL else FLAVOR[lang])]
    for k, (a, b) in EXTRA.items():
        out.append((k, a if zh else b))
    return out


for lang, fname in (("zh", "zh.csv"), ("en", "en.csv")):
    path = os.path.join(OUT, fname)
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write("# FreeChem localization — key,text\n")
        w = csv.writer(f, lineterminator="\n")
        for k, v in rows(lang):
            w.writerow([k, v])
    print(fname, len(rows(lang)), "entries")

# 校验
with open(os.path.join(OUT, "en.csv"), encoding="utf-8") as f:
    en = dict(r for r in csv.reader(f) if r and not r[0].startswith("#"))
leaked = [k for k, v in en.items() if re.search(r"[\u4e00-\u9fff]", v)]
print("en.csv 中文残留:", leaked or "无")
missing = [i for i in all_ids if i + "_name" not in en]
print("缺名称键:", missing or "无")
